186		} else {
187			b = append(b, "课程要求：\n"...)
188			for _, st := range rep.Requirements {
189				courseName := ""
190				credit := 0
191				if st.Course != nil {
192					courseName = st.Course.Name
193					credit = st.Course.Credit
194				}
