207							"  - 要求 %s（课程 %s《%s》，%d 学分）：已满足，来源为通过修读 %s",
208							st.Req.ID, st.Req.CourseID, courseName, credit,
209							st.PassedEnrollmentID)...)
210						if len(st.PassedEnrollmentIDs) > 1 {
211							b = append(b, fmt.Sprintf("（共通过 %d 次，仅计一次学分）",
212								len(st.PassedEnrollmentIDs))...)
213						}
214					}
215				} else {
216					b = append(b, fmt.Sprintf(
217						"  - 要求 %s（课程 %s《%s》，%d 学分）：未满足",
218						st.Req.ID, st.Req.CourseID, courseName, credit)...)
219				}
220				b = append(b, '\n')
221			}
222		}
223		if len(rep.Unmet) > 0 {
224			b = append(b, fmt.Sprintf("未满足要求：%v\n", rep.Unmet)...)
225		} else {
226			b = append(b, "未满足要求：（无）\n"...)
227		}
228		if len(rep.RejectedWaivers) > 0 {
229			b = append(b, "被拒绝的免修：\n"...)
230			for _, rj := range rep.RejectedWaivers {
231				b = append(b, fmt.Sprintf("  - 免修 %s（要求 %s，依据 %q）：%s\n",
232					rj.Waiver.ID, rj.Waiver.ReqID, rj.Waiver.Basis, rj.Reason)...)
233			}
234		}
235		if len(rep.RevokedWaivers) > 0 {
236			b = append(b, fmt.Sprintf("已撤销免修：%v（原依据与撤销状态保留在免修历史中）\n",
237				rep.RevokedWaivers)...)
238		}
239		return string(b)
240	}
