1	package credit
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件回归“读取已有记录时，有效免修的依据校验与首次正常申请一致”：
11	// 状态为有效（approved）的免修，依据必须含有实际文字；依据为空，或全部
12	// 由空白字符（空格、制表符、换行、回车、全角空格 U+3000、不换行空格
13	// U+00A0 等，允许混用）组成时，整份记录按内容损坏拒绝读取，即使该要求
14	// 另有通过修读也不能绕过。已拒绝申请的依据允许为空或只含空白；依据含
15	// 实际文字时其前后与中间的空白必须原样保留，读取不得修剪或改写。
16	//
17	// 这类矛盾无法经正常申请流程产生（空白依据的首次申请会被业务拒绝并记为
18	// rejected），因此损坏用例直接构造记录文件，聚焦 Load 读取历史这一路径。
19	
20	// blankBasisBase 构造结构完整、引用齐全的基础记录：学生 s1 的要求 r1
21	// 指向 4 学分课程 c1。withPass 时再附一条已通过修读 e1。
22	func blankBasisBase(withPass bool) *fileData {
23		d := &fileData{
24			Version:      recordVersion,
25			Courses:      []*Course{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
26			Students:     []*Student{{ID: "s1"}},
27			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
28		}
29		if withPass {
30			d.Enrollments = []*Enrollment{{
31				ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春",
32				Result: Passed, ResultSeq: 1,
33			}}
34			d.NextResultSeq = 1
35		}
36		return d
37	}
38	
39	// TestLoadRejectsApprovedWaiverWithBlankBasis 有效免修依据为空或全部为空白
40	// 字符时，无论空白由哪些字符、以什么方式混合组成，Load 都必须判为内容
41	// 损坏：错误点名记录文件、所属学生与免修编号，文件标记为已存在，原文件
42	// 逐字节保留，且不能返回可用于核对的 store。
43	func TestLoadRejectsApprovedWaiverWithBlankBasis(t *testing.T) {
44		blanks := map[string]string{
45			"空字符串":        "",
46			"普通空格":        "     ",
47			"制表符换行回车":     "\t\n\r\n\t",
48			"全角空格":        "　　　",
49			"不换行空格":       "     ",
50			"混合空白":        " \t　 \n  \r　",
51			"空白夹在前后无实际文字": "\n\t　  ",
52		}
53		for name, basis := range blanks {
54			t.Run(name, func(t *testing.T) {
55				d := blankBasisBase(false)
56				d.Waivers = []*Waiver{{
57					ID: "w1", StudentID: "s1", ReqID: "r1",
58					Basis: basis, Status: WaiverApproved,
59				}}
60				path, raw := writeRecord(t, d)
61	
62				s, existed, err := Load(path)
63				if err == nil {
64					t.Fatalf("有效免修依据为空白（%s）应判内容损坏拒绝读取，却得到 store=%v", name, s)
65				}
66				if !existed {
67					t.Fatalf("损坏文件应标记为已存在，existed=%v err=%v", existed, err)
68				}
69				msg := err.Error()
70				for _, want := range []string{path, "内容损坏", "s1", "w1", "有效免修", "依据"} {
71					if !strings.Contains(msg, want) {
72						t.Fatalf("错误信息应包含 %q（文件/学生/免修编号/缺少依据），得到：%v",
73							want, err)
74					}
75				}
76	
77				got, readErr := os.ReadFile(path)
78				if readErr != nil {
79					t.Fatal(readErr)
80				}
81				if string(got) != string(raw) {
82					t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
83				}
84			})
85		}
86	}
87	
88	// TestLoadBlankBasisApprovedNotMaskedByPassedEnrollment 即使该要求另有通过
89	// 修读（本来足以解释学分、满足要求），有效免修缺少依据仍然让整份记录
90	// 损坏：不能拿着通过记录继续核对学分、输出总学分或要求已满足。
91	func TestLoadBlankBasisApprovedNotMaskedByPassedEnrollment(t *testing.T) {
92		d := blankBasisBase(true)
93		d.Waivers = []*Waiver{{
94			ID: "w1", StudentID: "s1", ReqID: "r1",
95			Basis: " 　\t \n ", Status: WaiverApproved,
96		}}
97		path, raw := writeRecord(t, d)
98	
99		s, existed, err := Load(path)
100		if err == nil {
101			t.Fatalf("另有通过修读也不能放过缺少依据的有效免修，得到 store=%v", s)
102		}
103		if !existed {
104			t.Fatalf("应标记文件已存在，existed=%v err=%v", existed, err)
105		}
106		if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
107			!strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") {
108			t.Fatalf("错误应点名 s1 的有效免修 w1 缺少依据，得到：%v", err)
