175		if st := rep.Requirements[0]; st.Source != "enrollment" || st.WaiverID != "" {
176			t.Fatalf("被拒绝的空白依据申请不能成为来源，得到 %+v", st)
177		}
178		if len(rep.RejectedWaivers) != 2 {
179			t.Fatalf("两条被拒绝历史都应保留，得到 %d 条", len(rep.RejectedWaivers))
180		}
181		for _, rj := range rep.RejectedWaivers {
