11	// 本文件从命令行入口回归“读取已有记录时，有效免修的依据校验与首次正常
12	// 申请一致”。状态为有效但依据为空或全部为空白字符（空格、制表符、换行、
13	// 全角空格 U+3000、不换行空格 U+00A0 等，允许混用）的免修无法经正常申请
14	// 流程产生（首次提交会被业务拒绝），所以损坏用例直接写出结构完整的记录
15	// 文件，每条断言都重新打开进程访问它：
16	//   - check、show 乃至写入类命令都沿用文件内容损坏的退出码 2，标准输出
17	//     不出现总学分、要求已满足或操作成功的说明，错误输出点名记录文件
18	//     内容损坏、哪名学生的哪份有效免修缺少依据，原文件逐字节保留；
19	//   - 即使该要求另有通过修读也不能绕过校验继续核对；
20	//   - 依据含实际文字、只是前后/中间带缩进与换行时正常读取，show 中仍能
21	//     查到依据原文；
22	//   - 已拒绝申请依据为空白时记录仍合法，拒绝状态与原因照常可查、不计学分；
23	//   - 用户首次正常提交空白依据申请仍按业务规则拒绝（退出码 1），申请与
24	//     拒绝原因保留，随后重新打开文件是合法记录。
25	
26	// blankBasisRecord 构造结构完整、引用齐全的记录：s1 的 r1 指向 4 学分
27	// 课程 c1。basis 决定有效免修 w1 的依据；withPass 时再附通过修读 e1。
28	func blankBasisRecord(basis string, withPass bool) *diskRecord {
29		d := &diskRecord{
30			Version:      1,
31			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
32			Students:     []diskStudent{{ID: "s1"}},
33			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
34			Waivers: []diskWaiver{
35				{ID: "w1", Student: "s1", Req: "r1", Basis: basis, Status: "approved"},
36			},
37		}
38		if withPass {
39			d.Enrollments = []diskEnr{{
40				ID: "e1", Student: "s1", Req: "r1", Term: "2024春",
41				Result: "passed", ResultSeq: 1,
42			}}
43			d.NextResultSeq = 1
44		}
45		return d
46	}
47	
48	// assertBlankBasisAccessRejected 用指定命令访问损坏文件：必须退出码 2、
49	// stdout 没有任何业务内容，stderr 点名文件损坏与学生、免修编号。
50	func assertBlankBasisAccessRejected(t *testing.T, file string, raw []byte,
51		args []string, label string) {
52		t.Helper()
53		out, errText, code := runCLI(t, file, args...)
54		if code != exitFile {
55			t.Fatalf("%s：访问含空白依据有效免修的记录应退出码 %d，code=%d out=%q err=%q",
56				label, exitFile, code, out, errText)
57		}
58		if out != "" {
59			t.Fatalf("%s：拒绝整份记录时标准输出不应有任何业务内容，out=%q", label, out)
60		}
61		for _, banned := range []string{"总学分", "已满足", "成功"} {
62			if strings.Contains(out, banned) {
63				t.Fatalf("%s：标准输出不能出现 %q 类说明，out=%q", label, banned, out)
64			}
65		}
66		for _, want := range []string{file, "内容损坏", "s1", "w1", "有效免修", "依据"} {
67			if !strings.Contains(errText, want) {
68				t.Fatalf("%s：错误输出应点名文件/学生 s1/有效免修 w1/缺少依据（缺 %q），err=%q",
69					label, want, errText)
70			}
71		}
72		assertFileByteIdentical(t, file, raw, label+"：")
73	}
74	
75	// TestCLIApprovedWaiverBlankBasisRejectsAllCommands 有效免修依据为空白时，
76	// 无论用哪条命令打开（只读核对、历史查看、列课程，还是本来会保存变更的
77	// 登记），都必须在读取阶段以退出码 2 拒绝：不输出任何业务结果，错误说明
78	// 记录文件内容损坏、s1 的有效免修 w1 缺少依据，原文件保持不变。
79	func TestCLIApprovedWaiverBlankBasisRejectsAllCommands(t *testing.T) {
80		blanks := map[string]string{
81			"空字符串":  "",
82			"普通空格":  "     ",
83			"制表符换行": "\t\n\r\n\t",
84			"全角空格":  "　　　",
85			"不换行空格": "     ",
86			"混合空白":  " \t　 \n  \r　",
87		}
88		for name, basis := range blanks {
89			t.Run(name, func(t *testing.T) {
90				file, raw := writeDiskRecord(t, blankBasisRecord(basis, false))
91	
92				assertBlankBasisAccessRejected(t, file, raw,
93					[]string{"check", "s1"}, "check 当事学生")
94				assertBlankBasisAccessRejected(t, file, raw,
95					[]string{"show", "s1"}, "show 当事学生")
96				assertBlankBasisAccessRejected(t, file, raw,
97					[]string{"list-courses"}, "list-courses")
98	
99				// 写入类命令：同样在读取阶段拒绝，不能覆盖原文件或新增业务记录。
100				assertBlankBasisAccessRejected(t, file, raw,
101					[]string{"student", "s9"}, "写入类命令 student")
102	
103				// 查询文件里根本不存在的学生也不能绕过：整份文件不可读。
104				assertBlankBasisAccessRejected(t, file, raw,
105					[]string{"check", "ghost"}, "check 其他学生")
106	
107				assertFileByteIdentical(t, file, raw, "全部访问后：")
108			})
109		}
110	}
111	
112	// TestCLIBlankBasisApprovedNotMaskedByPassedEnrollment 即使该要求另有通过
113	// 修读（本来足以解释学分、满足要求），有效免修缺少依据仍必须以退出码 2
114	// 拒绝：不能出现总学分、要求已满足或通过修读来源的说明，文件原样保留。
115	func TestCLIBlankBasisApprovedNotMaskedByPassedEnrollment(t *testing.T) {
116		file, raw := writeDiskRecord(t, blankBasisRecord(" 　\t \n ", true))
117	
118		out, errText, code := runCLI(t, file, "check", "s1")
119		if code != exitFile {
120			t.Fatalf("通过修读不能掩盖缺少依据的有效免修，code=%d out=%q err=%q",
121				code, out, errText)
122		}
123		if out != "" {
124			t.Fatalf("损坏记录不得输出任何核对结果，out=%q", out)
125		}
126		for _, banned := range []string{"总学分", "已满足", "通过修读"} {
127			if strings.Contains(out, banned) {
128				t.Fatalf("标准输出不能出现 %q，out=%q", banned, out)
129			}
130		}
131		if !strings.Contains(errText, "内容损坏") || !strings.Contains(errText, "s1") ||
132			!strings.Contains(errText, "w1") || !strings.Contains(errText, file) {
133			t.Fatalf("错误应点名 %s 中 s1 的有效免修 w1 缺少依据，err=%q", file, errText)
134		}
135	
136		// 本来会保存变更的登记也必须停在读取阶段，原文件（含通过修读）保留。
137		out, errText, code = runCLI(t, file, "course-close", "c1")
138		if code != exitFile || out != "" {
139			t.Fatalf("写入类命令也应在读取阶段拒绝，code=%d out=%q err=%q",
140				code, out, errText)
141		}
142		assertFileByteIdentical(t, file, raw, "登记尝试后：")
143	}
144	
145	// TestCLIApprovedWaiverBasisWithWhitespaceAndTextOpensNormally 依据含有实际
146	// 文字、只是前后或中间带缩进、换行、全角空格与不换行空格时，记录必须正常
147	// 读取：check 以免修计 4 学分、要求已满足；show 展示的依据与保存原文一致
148	// （以 Go 引用形式出现，空白被转义但内容不缺）；只读访问不改文件。
149	func TestCLIApprovedWaiverBasisWithWhitespaceAndTextOpensNormally(t *testing.T) {
150		basis := "\t\n  学科竞赛获奖证明　 \n  证书编号：001  \n  "
151		d := blankBasisRecord(basis, false)
152		file, raw := writeDiskRecord(t, d)
153	
154		out, _, code := runCLI(t, file, "check", "s1")
155		if code != 0 {
156			t.Fatalf("含实际文字的依据应正常核对，code=2? out=%q", out)
157		}
158		if !strings.Contains(out, "总学分：4") ||
159			!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：已满足") ||
160			!strings.Contains(out, "来源为有效免修 w1") {
161			t.Fatalf("应凭有效免修 w1 满足 r1、计 4 学分，out=%q", out)
162		}
163		if strings.Contains(out, "未满足要求：[") {
164			t.Fatalf("r1 不应列为未满足，out=%q", out)
165		}
166	
167		show, _, code := runCLI(t, file, "show", "s1")
168		if code != 0 {
169			t.Fatalf("show 应成功，code=%d out=%q", code, show)
170		}
171		// 命令行以 %q 呈现依据，期望片段按同样方式引用，验证原文逐字符可查。
172		want := fmt.Sprintf("免修 w1：要求 r1，依据 %s，状态：有效", fmt.Sprintf("%q", basis))
173		if !strings.Contains(show, want) {
174			t.Fatalf("show 应展示未被修剪的依据原文\nwant contains %q\nout=%q", want, show)
175		}
176	
177		assertFileByteIdentical(t, file, raw, "check/show 之后：")
178	}
179	
180	// TestCLIRejectedWaiverWithBlankBasisOpensNormally 已拒绝申请的依据为空白
181	// 时记录仍合法：拒绝状态与原因在 check/show 中照常可查、不获得学分，要求
182	// 由同记录中的通过修读满足；只读访问不改文件。
183	func TestCLIRejectedWaiverWithBlankBasisOpensNormally(t *testing.T) {
184		d := &diskRecord{
185			Version:      1,
186			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
187			Students:     []diskStudent{{ID: "s1"}},
188			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
189			Enrollments: []diskEnr{{
190				ID: "e1", Student: "s1", Req: "r1", Term: "2024春",
191				Result: "passed", ResultSeq: 1,
192			}},
193			NextResultSeq: 1,
194			Waivers: []diskWaiver{
195				{ID: "wr", Student: "s1", Req: "r1", Basis: " \t　 \n ",
196					Status: "rejected", Reason: "免修依据为空"},
197			},
198		}
199		file, raw := writeDiskRecord(t, d)
200	
201		out, _, code := runCLI(t, file, "check", "s1")
202		if code != 0 {
203			t.Fatalf("被拒绝的空白依据申请不应判坏文件，code=%d out=%q", code, out)
204		}
205		if !strings.Contains(out, "总学分：4") ||
206			!strings.Contains(out, "来源为通过修读 e1") {
207			t.Fatalf("r1 应由通过修读满足、计 4 学分，out=%q", out)
208		}
209		if !strings.Contains(out, "免修 wr") || !strings.Contains(out, "免修依据为空") {
210			t.Fatalf("被拒绝申请及原因应在核对中可查，out=%q", out)
211		}
212		if strings.Contains(out, "来源为有效免修") {
213			t.Fatalf("被拒绝申请不能成为有效来源，out=%q", out)
214		}
215		show, _, code := runCLI(t, file, "show", "s1")
216		if code != 0 || !strings.Contains(show, "状态：已拒绝（免修依据为空）") {
217			t.Fatalf("show 应保留被拒绝状态与原因，code=%d out=%q", code, show)
218		}
219		assertFileByteIdentical(t, file, raw, "只读访问之后：")
220	}
221	
222	// TestCLIFirstTimeBlankBasisSubmissionStillBusinessRejection 用户首次正常
223	// 提交纯空白依据申请的行为不变：按业务规则以退出码 1 拒绝，申请内容与
224	// 拒绝原因保留在免修历史并落盘；随后重新打开是合法记录（退出码 0），
225	// 核对中可查到该拒绝记录，且不会被读取校验反过来判成内容损坏。
226	func TestCLIFirstTimeBlankBasisSubmissionStillBusinessRejection(t *testing.T) {
227		file := filepath.Join(t.TempDir(), "records.json")
228		for _, st := range [][]string{
229			{"student", "s1"},
230			{"course", "c1", "数学", "4"},
231			{"req", "s1", "r1", "c1"},
232		} {
233			if _, errText, code := runCLI(t, file, st...); code != 0 {
234				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
235			}
236		}
237	
238		// 依据只含全角空格、不换行空格与制表换行：业务拒绝退出码 1。
239		out, errText, code := runCLI(t, file, "waiver", "s1", "r1", "w1", " 　 \t \n ")
240		if code != exitRejected {
241			t.Fatalf("首次提交空白依据应按业务规则以退出码 1 拒绝，code=%d out=%q err=%q",
242				code, out, errText)
243		}
244		if !strings.Contains(out, "已拒绝") {
245			t.Fatalf("应说明申请已拒绝并记入免修历史，out=%q", out)
246		}
247	
248		// 文件已保存，重新打开必须是合法记录：check 退出码 0，拒绝记录可查、
249		// r1 未满足、学分为零。
250		out, _, code = runCLI(t, file, "check", "s1")
251		if code != 0 {
252			t.Fatalf("保存了被拒绝申请的文件应正常打开，code=%d out=%q", code, out)
253		}
254		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
255			t.Fatalf("被拒绝的空白依据申请不获得学分，out=%q", out)
256		}
257		if !strings.Contains(out, "免修 w1") || !strings.Contains(out, "免修依据为空") {
258			t.Fatalf("核对中应保留被拒绝申请与原因，out=%q", out)
259		}
260	
261		// show 同样正常，状态为已拒绝；该文件绝不会被判成内容损坏。
262		show, _, code := runCLI(t, file, "show", "s1")
263		if code != 0 || !strings.Contains(show, "免修 w1") ||
264			!strings.Contains(show, "状态：已拒绝（免修依据为空）") {
265			t.Fatalf("show 应能查到被拒绝的空白依据申请，code=%d out=%q", code, show)
266		}
267	
268		// 文件确实存在且为一份完整记录。
269		if got, err := os.ReadFile(file); err != nil || !strings.Contains(string(got), `"status": "rejected"`) {
