21	
22		// 文件不存在时从空记录开始。
23		out, _, code := runCLI(t, file, "student", "s1")
24		if code != 0 || !strings.Contains(out, "已登记学生") {
25			t.Fatalf("登记学生失败 code=%d out=%q", code, out)
26		}
