40		}
41		if _, _, code := runCLI(t, file, "req", "s1", "r2", "c2"); code != 0 {
42			t.Fatal("登记要求失败")
43		}
44	
45		// 同一学生重复要求被拒绝。
46		if _, errText, code := runCLI(t, file, "req", "s1", "r3", "c1"); code == 0 {
47			t.Fatalf("重复课程要求应被拒绝，err=%q", errText)
48		}
49	
50		// 修读：同学期两次，不同编号。
51		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e1"); code != 0 {
52			t.Fatal("选课 e1 失败")
53		}
54		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e2"); code != 0 {
55			t.Fatal("选课 e2 失败")
56		}
57		// e1 未通过，e2 通过。
58		if _, _, code := runCLI(t, file, "fail", "s1", "e1"); code != 0 {
59			t.Fatal("提交未通过失败")
60		}
61		if _, _, code := runCLI(t, file, "pass", "s1", "e2"); code != 0 {
62			t.Fatal("提交通过失败")
63		}
64		// 改结果应被拒绝。
65		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code == 0 {
66			t.Fatalf("未通过改通过应被拒绝，err=%q", errText)
67		}
68	
69		// r2 用免修满足。
70		if out, _, code := runCLI(t, file, "waiver", "s1", "r2", "w1", "竞赛获奖"); code != 0 ||
71			!strings.Contains(out, "有效") {
72			t.Fatalf("免修应有效 code=%d out=%q", code, out)
73		}
74	
75		// 重新打开进程核对：状态已持久化。
76		out, _, code = runCLI(t, file, "check", "s1")
77		if code != 0 {
78			t.Fatalf("核对失败 code=%d out=%q", code, out)
79		}
80		if !strings.Contains(out, "总学分：7") {
81			t.Fatalf("总学分应为 7（4+3），out=%q", out)
82		}
83		if !strings.Contains(out, "通过修读 e2") {
84			t.Fatalf("应以通过修读 e2 说明 r1 来源，out=%q", out)
85		}
86		if !strings.Contains(out, "有效免修 w1") {
87			t.Fatalf("应以免修 w1 说明 r2 来源，out=%q", out)
88		}
89		if strings.Contains(out, "未满足要求：[") {
90			t.Fatalf("不应有未满足要求，out=%q", out)
91		}
92	
93		// 停开课程后不能新增修读。
94		if _, _, code := runCLI(t, file, "course-close", "c2"); code != 0 {
95			t.Fatal("停开课程失败")
96		}
97		if _, errText, code := runCLI(t, file, "enroll", "s1", "r2", "2025春", "e3"); code == 0 {
98			t.Fatalf("停开后新增修读应被拒绝，err=%q", errText)
99		}
100	}
101	
102	func TestCLIPersistenceAndRevoke(t *testing.T) {
103		file := filepath.Join(t.TempDir(), "records.json")
104		steps := [][]string{
105			{"student", "s1"},
106			{"course", "c1", "数学", "4"},
107			{"req", "s1", "r1", "c1"},
108			{"enroll", "s1", "r1", "2024春", "e1"},
109			{"pass", "s1", "e1"},
110			{"waiver", "s1", "r1", "w1", "依据"},
111		}
112		for _, st := range steps {
113			if _, _, code := runCLI(t, file, st...); code != 0 {
114				t.Fatalf("步骤 %v 失败", st)
115			}
116		}
117	
118		// 通过与免修并存只计一次，核对以免修说明来源。
119		out, _, code := runCLI(t, file, "check", "s1")
120		if code != 0 {
121			t.Fatalf("核对失败：%s", out)
122		}
123		if !strings.Contains(out, "总学分：4") {
124			t.Fatalf("只应计一份 4 学分，out=%q", out)
125		}
126		if !strings.Contains(out, "来源为有效免修 w1") {
127			t.Fatalf("应以免修说明来源，out=%q", out)
128		}
129		if !strings.Contains(out, "通过修读历史") {
130			t.Fatalf("应保留通过修读历史，out=%q", out)
131		}
132	
133		// 撤销后有通过记录，继续满足。
134		if _, _, code := runCLI(t, file, "revoke-waiver", "s1", "w1", "原因"); code != 0 {
135			t.Fatal("撤销免修失败")
136		}
137		out, _, code = runCLI(t, file, "check", "s1")
138		if code != 0 || !strings.Contains(out, "总学分：4") {
139			t.Fatalf("撤销后有通过记录应继续满足，code=%d out=%q", code, out)
140		}
141		if !strings.Contains(out, "来源为通过修读 e1") {
142			t.Fatalf("撤销后应改以通过修读说明来源，out=%q", out)
143		}
144	
145		// show 能查到免修历史中的撤销状态。
146		out, _, code = runCLI(t, file, "show", "s1")
147		if code != 0 || !strings.Contains(out, "状态：已撤销") {
148			t.Fatalf("show 应展示已撤销免修，code=%d out=%q", code, out)
149		}
150	}
151	
152	func TestCLIRejectedWaiverHistoryPersists(t *testing.T) {
153		file := filepath.Join(t.TempDir(), "records.json")
154		runCLI(t, file, "student", "s1")
155		runCLI(t, file, "course", "c1", "数学", "4")
