157		// 目标要求不存在：拒绝（退出码 1）但内容与原因入历史并保存。
158		outText, _, code := runCLI(t, file, "waiver", "s1", "rX", "wbad", "依据")
159		if code != 1 || !strings.Contains(outText, "已拒绝") {
