171	func TestCLIRejectedWaiverResubmitAfterReqCreated(t *testing.T) {
172		file := filepath.Join(t.TempDir(), "records.json")
173		runCLI(t, file, "student", "s1")
174		runCLI(t, file, "course", "c1", "数学", "4")
175	
176		// 首次申请：目标要求不存在，退出码 1，内容与原因记入免修历史。
177		out, _, code := runCLI(t, file, "waiver", "s1", "r1", "w1", "学科竞赛获奖")
178		if code != 1 || !strings.Contains(out, "已拒绝") {
179			t.Fatalf("目标要求不存在的首次申请应拒绝且退出码 1，code=%d out=%q", code, out)
180		}
181	
182		// 后来补建同编号要求。
183		if _, _, code := runCLI(t, file, "req", "s1", "r1", "c1"); code != 0 {
184			t.Fatal("补建要求失败")
185		}
186	
187		// 按相同内容再次提交：沿用重复提交成功的退出码 0，但状态仍为已拒绝，
188		// 不能被当成免修获批。重复执行结果不变。
189		for i := 0; i < 2; i++ {
190			out, _, code := runCLI(t, file, "waiver", "s1", "r1", "w1", "学科竞赛获奖")
191			if code != 0 {
192				t.Fatalf("第 %d 次重复提交应幂等成功，code=%d out=%q", i+1, code, out)
193			}
194			if !strings.Contains(out, "已拒绝") || strings.Contains(out, "有效") {
195				t.Fatalf("重复提交应显示原申请仍为已拒绝，out=%q", out)
196			}
197		}
198	
199		// 核对：要求仍未满足，总学分为零，被拒绝记录展示原编号、要求、依据与原因。
200		out, _, code = runCLI(t, file, "check", "s1")
201		if code != 0 {
202			t.Fatalf("核对失败 code=%d out=%q", code, out)
203		}
